@page "/apply"
@rendermode InteractiveServer
@using sv_8d1d4eac22a44063b802dd0696a043ce.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* ── Step Indicator Bar ── *@
<nav class="step-indicator" aria-label="Application steps">
    @for (int i = 0; i < _stepNames.Length; i++)
    {
        var step = i + 1;
        var css = step == _currentStep ? "step active"
                : step < _currentStep ? "step completed"
                : "step";

        <button class="@css"
                disabled="@(step >= _currentStep)"
                @onclick="() => GoToStep(step)">
            <span class="step-number">
                @if (step < _currentStep)
                {
                    <span>✓</span>
                }
                else
                {
                    @step
                }
            </span>
            <span class="step-label">@_stepNames[i]</span>
        </button>

        @if (i < _stepNames.Length - 1)
        {
            <span class="step-connector @(step < _currentStep ? "done" : "")"></span>
        }
    }
</nav>

@* ── Validation errors ── *@
@if (_errors.Count > 0)
{
    <div class="alert alert-danger mt-3">
        <ul class="mb-0">
            @foreach (var err in _errors)
            {
                <li>@err</li>
            }
        </ul>
    </div>
}

@* ── Step Content ── *@
<div class="step-content mt-4">

    @* ── Step 1: Personal Info ── *@
    @if (_currentStep == 1)
    {
        <h3>Personal Information</h3>
        <div class="mb-3">
            <label class="form-label">Full Name <span class="text-danger">*</span></label>
            <input class="form-control" @bind="_fullName" placeholder="Jane Doe" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email <span class="text-danger">*</span></label>
            <input class="form-control" type="email" @bind="_email" placeholder="jane@example.com" />
        </div>
        <div class="mb-3">
            <label class="form-label">Phone <span class="text-danger">*</span></label>
            <input class="form-control" type="tel" @bind="_phone" placeholder="(555) 123-4567" />
        </div>
        <div class="mb-3">
            <label class="form-label">Address <span class="text-danger">*</span></label>
            <textarea class="form-control" @bind="_address" rows="2" placeholder="123 Main St, City, State ZIP"></textarea>
        </div>

