                            <span class="text-muted">@r.Email · @r.Phone</span>
                        </div>
                    }
                </div>
            </div>

            @* Cover Letter *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Cover Letter</strong>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(4)">Edit</button>
                </div>
                <div class="card-body">
                    <p style="white-space: pre-wrap;">@_coverLetter</p>
                </div>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PrevStep">Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isLoading">
                    @if (_isLoading) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Submit Application
                </button>
            </div>
        }
    }
</div>

@code {
    private static readonly string[] _stepNames =
        ["Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"];

    private int _currentStep = 1;
    private List<string> _errors = [];
    private bool _isLoading;
    private bool _submitted;
    private int _applicationId;

    // Step 1
    private string _fullName = string.Empty;
    private string _email = string.Empty;
    private string _phone = string.Empty;
    private string _address = string.Empty;

    // Step 2
    private List<WorkEntryModel> _workEntries = [new()];

    // Step 3
    private List<ReferenceModel> _references = [new(), new()];

    // Step 4
    private string _coverLetter = string.Empty;

    // Mutable wrappers around the immutable records for form binding
    private record WorkEntryModel
    {
        public string Company { get; set; } = string.Empty;
        public string Title { get; set; } = string.Empty;
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = string.Empty;
    }

    private record ReferenceModel
    {
        public string Name { get; set; } = string.Empty;
        public string Relationship { get; set; } = string.Empty;
        public string Email { get; set; } = string.Empty;
        public string Phone { get; set; } = string.Empty;
    }

    private void GoToStep(int step)
    {
        if (step < _currentStep)
        {
            _errors.Clear();
            _currentStep = step;
        }
    }

    private void PrevStep()
    {
        _errors.Clear();
        if (_currentStep > 1) _currentStep--;
    }

    private async Task NextStep()
    {
        _errors.Clear();

        if (!ValidateCurrentStep())
            return;

        if (_currentStep == 1)
        {
            _isLoading = true;
            var emailValid = await ApplicationService.ValidateEmailAsync(_email);
            _isLoading = false;
            if (!emailValid)
            {
                _errors.Add("Please enter a valid email address.");
                return;
            }
        }

        if (_currentStep < _stepNames.Length)
            _currentStep++;
    }

    private bool ValidateCurrentStep()
    {
        switch (_currentStep)
        {
            case 1:
                if (string.IsNullOrWhiteSpace(_fullName)) _errors.Add("Full name is required.");
                if (string.IsNullOrWhiteSpace(_email)) _errors.Add("Email is required.");
                if (string.IsNullOrWhiteSpace(_phone)) _errors.Add("Phone is required.");
                if (string.IsNullOrWhiteSpace(_address)) _errors.Add("Address is required.");
                break;

            case 2:
                for (int i = 0; i < _workEntries.Count; i++)
                {
                    var e = _workEntries[i];
                    if (string.IsNullOrWhiteSpace(e.Company)) _errors.Add($"Position {i + 1}: Company is required.");
                    if (string.IsNullOrWhiteSpace(e.Title)) _errors.Add($"Position {i + 1}: Job title is required.");
                    if (e.StartDate == default) _errors.Add($"Position {i + 1}: Start date is required.");
                }
                break;

            case 3:
                for (int i = 0; i < _references.Count; i++)
                {
                    var r = _references[i];
                    if (string.IsNullOrWhiteSpace(r.Name)) _errors.Add($"Reference {i + 1}: Name is required.");
                    if (string.IsNullOrWhiteSpace(r.Relationship)) _errors.Add($"Reference {i + 1}: Relationship is required.");
                    if (string.IsNullOrWhiteSpace(r.Email)) _errors.Add($"Reference {i + 1}: Email is required.");
                    if (string.IsNullOrWhiteSpace(r.Phone)) _errors.Add($"Reference {i + 1}: Phone is required.");
                }
                break;

            case 4:
                if (string.IsNullOrWhiteSpace(_coverLetter)) _errors.Add("Cover letter is required.");
                break;
        }

        return _errors.Count == 0;
    }

    private void AddWorkEntry() => _workEntries.Add(new());
    private void RemoveWorkEntry(int idx) => _workEntries.RemoveAt(idx);
    private void UpdateWork(int idx, WorkEntryModel entry) => _workEntries[idx] = entry;

    private void AddReference() { if (_references.Count < 3) _references.Add(new()); }
    private void RemoveReference(int idx) => _references.RemoveAt(idx);
    private void UpdateRef(int idx, ReferenceModel entry) => _references[idx] = entry;

    private async Task SubmitApplication()
    {
        _isLoading = true;

        var personal = new PersonalInfo(_fullName, _email, _phone, _address);
        var workHistory = new WorkHistory(
            _workEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
        var references = _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
        var application = new JobApplication(personal, workHistory, references, _coverLetter);

        _applicationId = await ApplicationService.SubmitApplicationAsync(application);
        _submitted = true;
        _isLoading = false;
    }
}
