{"file_text": ".step-indicator {
    display: flex;
    align-items: center;
    gap: 0;
    padding: 1rem 0;
    flex-wrap: wrap;
}

.step-indicator .step {
    display: flex;
    flex-direction: column;
    align-items: center;
    background: none;
    border: none;
    cursor: default;
    padding: 0.25rem 0.5rem;
    min-width: 6rem;
    opacity: 0.4;
    transition: opacity 0.2s;
}

.step-indicator .step.active {
    opacity: 1;
}

.step-indicator .step.completed {
    opacity: 0.85;
    cursor: pointer;
}

.step-indicator .step.completed:hover {
    opacity: 1;
}

.step-number {
    width: 2rem;
    height: 2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    margin-bottom: 0.25rem;
    background: #dee2e6;
    color: #495057;
}

.step.active .step-number {
    background: #0d6efd;
    color: #fff;
}

.step.completed .step-number {
    background: #198754;
    color: #fff;
}

.step-label {
    font-size: 0.75rem;
    text-align: center;
    white-space: nowrap;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    min-width: 1rem;
    align-self: flex-start;
    margin-top: 1.25rem;
}

.step-connector.done {
    background: #198754;
}
