@page "/apply"
@rendermode InteractiveServer
@using sv_8d1d4eac22a44063b802dd0696a043ce.Models
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h1>Job Application</h1>

@* ── Step Indicator Bar ── *@
<nav class="step-indicator" aria-label="Application steps">
    @for (int i = 0; i < _stepNames.Length; i++)
    {
        var step = i + 1;
        var css = step == _currentStep ? "step active"
                : step < _currentStep ? "step completed"
                : "step";

        <button class="@css"
                disabled="@(step >= _currentStep)"
                @onclick="() => GoToStep(step)">
            <span class="step-number">
                @if (step < _currentStep)
                {
                    <span>✓</span>
                }
                else
                {
                    @step
                }
            </span>
            <span class="step-label">@_stepNames[i]</span>
        </button>

        @if (i < _stepNames.Length - 1)
        {
            <span class="step-connector @(step < _currentStep ? "done" : "")"></span>
        }
    }
</nav>

@* ── Validation errors ── *@
@if (_errors.Count > 0)
{
    <div class="alert alert-danger mt-3">
        <ul class="mb-0">
            @foreach (var err in _errors)
            {
                <li>@err</li>
            }
        </ul>
    </div>
}

@* ── Step Content ── *@
<div class="step-content mt-4">

    @* ── Step 1: Personal Info ── *@
    @if (_currentStep == 1)
    {
        <h3>Personal Information</h3>
        <div class="mb-3">
            <label class="form-label">Full Name <span class="text-danger">*</span></label>
            <input class="form-control" @bind="_fullName" placeholder="Jane Doe" />
        </div>
        <div class="mb-3">
            <label class="form-label">Email <span class="text-danger">*</span></label>
            <input class="form-control" type="email" @bind="_email" placeholder="jane@example.com" />
        </div>
        <div class="mb-3">
            <label class="form-label">Phone <span class="text-danger">*</span></label>
            <input class="form-control" type="tel" @bind="_phone" placeholder="(555) 123-4567" />
        </div>
        <div class="mb-3">
            <label class="form-label">Address <span class="text-danger">*</span></label>
            <textarea class="form-control" @bind="_address" rows="2" placeholder="123 Main St, City, State ZIP"></textarea>
        </div>

        <div class="d-flex justify-content-end">
            <button class="btn btn-primary" @onclick="NextStep" disabled="@_isLoading">
                @if (_isLoading) { <span class="spinner-border spinner-border-sm me-1"></span> }
                Next
            </button>
        </div>
    }

    @* ── Step 2: Work History ── *@
    else if (_currentStep == 2)
    {
        <h3>Work History</h3>
        @for (int i = 0; i < _workEntries.Count; i++)
        {
            var idx = i;
            var entry = _workEntries[idx];

            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h5 class="card-title mb-0">Position @(idx + 1)</h5>
                        @if (_workEntries.Count > 1)
                        {
                            <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveWorkEntry(idx)">Remove</button>
                        }
                    </div>

                    <div class="row mb-2">
                        <div class="col-md-6">
                            <label class="form-label">Company <span class="text-danger">*</span></label>
                            <input class="form-control" value="@entry.Company"
                                   @onchange="e => UpdateWork(idx, entry with { Company = (string?)e.Value ?? string.Empty })" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Job Title <span class="text-danger">*</span></label>
                            <input class="form-control" value="@entry.Title"
                                   @onchange="e => UpdateWork(idx, entry with { Title = (string?)e.Value ?? string.Empty })" />
                        </div>
                    </div>

                    <div class="row mb-2">
                        <div class="col-md-4">
                            <label class="form-label">Start Date <span class="text-danger">*</span></label>
                            <input class="form-control" type="date" value="@(entry.StartDate == default ? "" : entry.StartDate.ToString("yyyy-MM-dd"))"
                                   @onchange="e => UpdateWork(idx, entry with { StartDate = DateTime.TryParse((string?)e.Value, out var d) ? d : default })" />
                        </div>
                        <div class="col-md-4">
                            <label class="form-label">End Date</label>
                            <input class="form-control" type="date" disabled="@entry.IsCurrent"
                                   value="@(entry.EndDate?.ToString("yyyy-MM-dd") ?? "")"
                                   @onchange="e => UpdateWork(idx, entry with { EndDate = DateTime.TryParse((string?)e.Value, out var d) ? d : null })" />
                        </div>
                        <div class="col-md-4 d-flex align-items-end">
                            <div class="form-check mb-2">
                                <input class="form-check-input" type="checkbox" id="current-@idx" checked="@entry.IsCurrent"
                                       @onchange="e => UpdateWork(idx, entry with { IsCurrent = (bool)(e.Value ?? false), EndDate = (bool)(e.Value ?? false) ? null : entry.EndDate })" />
                                <label class="form-check-label" for="current-@idx">Currently working here</label>
                            </div>
                        </div>
                    </div>

                    <div class="mb-2">
                        <label class="form-label">Description</label>
                        <textarea class="form-control" rows="2" value="@entry.Description"
                                  @onchange="e => UpdateWork(idx, entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
                    </div>
                </div>
            </div>
        }

        <button class="btn btn-outline-secondary mb-3" @onclick="AddWorkEntry">
            + Add Another Position
        </button>

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PrevStep">Back</button>
            <button class="btn btn-primary" @onclick="NextStep">Next</button>
        </div>
    }

    @* ── Step 3: References ── *@
    else if (_currentStep == 3)
    {
        <h3>References</h3>
        @for (int i = 0; i < _references.Count; i++)
        {
            var idx = i;
            var refEntry = _references[idx];

            <div class="card mb-3">
                <div class="card-body">
                    <div class="d-flex justify-content-between align-items-center mb-2">
                        <h5 class="card-title mb-0">Reference @(idx + 1)</h5>
                        @if (_references.Count > 2)
                        {
                            <button class="btn btn-outline-danger btn-sm" @onclick="() => RemoveReference(idx)">Remove</button>
                        }
                    </div>
                    <div class="row mb-2">
                        <div class="col-md-6">
                            <label class="form-label">Name <span class="text-danger">*</span></label>
                            <input class="form-control" value="@refEntry.Name"
                                   @onchange="e => UpdateRef(idx, refEntry with { Name = (string?)e.Value ?? string.Empty })" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Relationship <span class="text-danger">*</span></label>
                            <input class="form-control" value="@refEntry.Relationship"
                                   @onchange="e => UpdateRef(idx, refEntry with { Relationship = (string?)e.Value ?? string.Empty })" />
                        </div>
                    </div>
                    <div class="row mb-2">
                        <div class="col-md-6">
                            <label class="form-label">Email <span class="text-danger">*</span></label>
                            <input class="form-control" type="email" value="@refEntry.Email"
                                   @onchange="e => UpdateRef(idx, refEntry with { Email = (string?)e.Value ?? string.Empty })" />
                        </div>
                        <div class="col-md-6">
                            <label class="form-label">Phone <span class="text-danger">*</span></label>
                            <input class="form-control" type="tel" value="@refEntry.Phone"
                                   @onchange="e => UpdateRef(idx, refEntry with { Phone = (string?)e.Value ?? string.Empty })" />
                        </div>
                    </div>
                </div>
            </div>
        }

        @if (_references.Count < 3)
        {
            <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
                + Add Reference
            </button>
        }

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PrevStep">Back</button>
            <button class="btn btn-primary" @onclick="NextStep">Next</button>
        </div>
    }

    @* ── Step 4: Cover Letter ── *@
    else if (_currentStep == 4)
    {
        <h3>Cover Letter</h3>
        <div class="mb-2">
            <textarea class="form-control" rows="10" @bind="_coverLetter" maxlength="2000"
                      placeholder="Tell us why you're a great fit for this role..."></textarea>
        </div>
        <div class="text-muted mb-3">@_coverLetter.Length / 2000 characters</div>

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="PrevStep">Back</button>
            <button class="btn btn-primary" @onclick="NextStep">Next</button>
        </div>
    }

    @* ── Step 5: Review & Submit ── *@
    else if (_currentStep == 5)
    {
        @if (_submitted)
        {
            <div class="text-center py-5">
                <h2 class="text-success">✓ Application Submitted!</h2>
                <p class="lead">Your application ID is <strong>#@_applicationId</strong></p>
                <p>We'll be in touch soon. Thank you for applying!</p>
            </div>
        }
        else
        {
            <h3>Review &amp; Submit</h3>

            @* Personal Info *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Personal Information</strong>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(1)">Edit</button>
                </div>
                <div class="card-body">
                    <dl class="row mb-0">
                        <dt class="col-sm-3">Name</dt><dd class="col-sm-9">@_fullName</dd>
                        <dt class="col-sm-3">Email</dt><dd class="col-sm-9">@_email</dd>
                        <dt class="col-sm-3">Phone</dt><dd class="col-sm-9">@_phone</dd>
                        <dt class="col-sm-3">Address</dt><dd class="col-sm-9">@_address</dd>
                    </dl>
                </div>
            </div>

            @* Work History *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Work History</strong>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(2)">Edit</button>
                </div>
                <div class="card-body">
                    @foreach (var entry in _workEntries)
                    {
                        <div class="mb-3 border-bottom pb-2">
                            <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                            <span class="text-muted">
                                @entry.StartDate.ToString("MMM yyyy") –
                                @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                            </span>
                            @if (!string.IsNullOrWhiteSpace(entry.Description))
                            {
                                <p class="mt-1 mb-0">@entry.Description</p>
                            }
                        </div>
                    }
                </div>
            </div>

            @* References *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>References</strong>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(3)">Edit</button>
                </div>
                <div class="card-body">
                    @foreach (var r in _references)
                    {
                        <div class="mb-2">
                            <strong>@r.Name</strong> — @r.Relationship<br />
                            <span class="text-muted">@r.Email · @r.Phone</span>
                        </div>
                    }
                </div>
            </div>

            @* Cover Letter *@
            <div class="card mb-3">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>Cover Letter</strong>
                    <button class="btn btn-link btn-sm p-0" @onclick="() => GoToStep(4)">Edit</button>
                </div>
                <div class="card-body">
                    <p style="white-space: pre-wrap;">@_coverLetter</p>
                </div>
            </div>

            <div class="d-flex justify-content-between">
                <button class="btn btn-secondary" @onclick="PrevStep">Back</button>
                <button class="btn btn-success btn-lg" @onclick="SubmitApplication" disabled="@_isLoading">
                    @if (_isLoading) { <span class="spinner-border spinner-border-sm me-1"></span> }
                    Submit Application
                </button>
            </div>
        }
    }
</div>

